begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('eee00000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'photo-'||i||'@test.invalid','{"display_name":"Photo Fixture"}'::jsonb from generate_series(1,4)i;
insert into public.staff_accounts(id,email,display_name) select id,email,'Photo Fixture' from auth.users where email like 'photo-%@test.invalid';
insert into public.staff_roles values('eee00000-0000-4000-8000-000000000001','organizer'),('eee00000-0000-4000-8000-000000000002','trainer'),('eee00000-0000-4000-8000-000000000003','trainer'),('eee00000-0000-4000-8000-000000000004','main_judge');
insert into public.teams(id,name,region) values('eee10000-0000-4000-8000-000000000001','Photo Club A','Test'),('eee10000-0000-4000-8000-000000000002','Photo Club B','Test');
insert into public.trainer_profiles(user_id,team_id) values('eee00000-0000-4000-8000-000000000002','eee10000-0000-4000-8000-000000000001'),('eee00000-0000-4000-8000-000000000003','eee10000-0000-4000-8000-000000000002');
insert into public.players(id,team_id,first_name,last_name,gender,date_of_birth,playing_hand,playing_style,sports_level) values('eee20000-0000-4000-8000-000000000001','eee10000-0000-4000-8000-000000000001','Photo','Player','boy','2014-01-01','right','attack','junior');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eee00000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.begin_player_photo('eee30000-0000-4000-8000-000000000001','eee20000-0000-4000-8000-000000000001','image/png','application/pdf',4,4,repeat('a',64),repeat('b',64),true)$$,'42501','Photo upload permission required','other club cannot reserve photo upload');
select set_config('request.jwt.claims','{"sub":"eee00000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.begin_player_photo('eee30000-0000-4000-8000-000000000001','eee20000-0000-4000-8000-000000000001','image/png','application/pdf',4,4,repeat('a',64),repeat('b',64),true)$$,'42501','Photo upload permission required','Main Judge alone cannot upload consent');
select set_config('request.jwt.claims','{"sub":"eee00000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.begin_player_photo('eee30000-0000-4000-8000-000000000001','eee20000-0000-4000-8000-000000000001','image/png','application/pdf',4,4,repeat('a',64),repeat('b',64),false)$$,'22023','Written guardian permission required','permission declaration required');
select lives_ok($$select public.begin_player_photo('eee30000-0000-4000-8000-000000000001','eee20000-0000-4000-8000-000000000001','image/png','application/pdf',4,4,repeat('a',64),repeat('b',64),true)$$,'own Trainer reserves upload');
select lives_ok($$select public.begin_player_photo('eee30000-0000-4000-8000-000000000001','eee20000-0000-4000-8000-000000000001','image/png','application/pdf',4,4,repeat('a',64),repeat('b',64),true)$$,'same upload retry accepted');
select throws_ok($$select public.begin_player_photo('eee30000-0000-4000-8000-000000000001','eee20000-0000-4000-8000-000000000001','image/png','application/pdf',4,4,repeat('c',64),repeat('b',64),true)$$,'22023','Photo upload payload conflict','different bytes cannot reuse upload ID');
select throws_ok($$select public.finish_player_photo('eee30000-0000-4000-8000-000000000001')$$,'22023','Both private uploads required','cannot finalize missing files');
select throws_ok($$update public.player_photo_assets set state='approved'$$,'42501',null,'direct approval denied');
select throws_ok($$insert into public.public_player_photos(player_id,asset_id,content_base64,content_sha256) values('eee20000-0000-4000-8000-000000000001','eee30000-0000-4000-8000-000000000001','/9j/2Q==',repeat('a',64))$$,'42501',null,'direct public image insertion denied');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('player-private','unreserved/path','{}')$$,'42501',null,'unreserved upload path denied');
select lives_ok($$insert into storage.objects(bucket_id,name,metadata) select 'player-private',photo_path,'{"size":4,"mimetype":"image/png"}'::jsonb from public.player_photo_assets where id='eee30000-0000-4000-8000-000000000001'$$,'reserved original path allowed');
select lives_ok($$insert into storage.objects(bucket_id,name,metadata) select 'player-private',evidence_path,'{"size":4,"mimetype":"application/pdf"}'::jsonb from public.player_photo_assets where id='eee30000-0000-4000-8000-000000000001'$$,'reserved consent path allowed');
select lives_ok($$select public.finish_player_photo('eee30000-0000-4000-8000-000000000001')$$,'two uploaded objects reach pending review');
select is((select state::text from public.player_photo_assets where id='eee30000-0000-4000-8000-000000000001'),'pending_review','state remains unpublished');
select throws_ok($$select public.review_player_photo('eee30000-0000-4000-8000-000000000001','approve','Self approval','{"jpeg_base64":"/9j/2Q=="}')$$,'42501','Organizer required','Trainer cannot approve own photo');
select is((select count(*)::int from public.public_player_photos where player_id='eee20000-0000-4000-8000-000000000001'),0,'pending photo has no public projection');
select set_config('request.jwt.claims','{"sub":"eee00000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is(private.can_read_photo_object('eee20000-0000-4000-8000-000000000001/eee30000-0000-4000-8000-000000000001/consent'),false,'Main Judge cannot read guardian evidence');
select set_config('request.jwt.claims','{"sub":"eee00000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.review_player_photo('eee30000-0000-4000-8000-000000000001','approve','Reviewed')$$,'22023','Bounded JPEG publication required','approval requires sanitized JPEG payload');
select lives_ok($$select public.review_player_photo('eee30000-0000-4000-8000-000000000001','approve','Written consent reviewed',jsonb_build_object('jpeg_base64',encode(decode('ffd8ff','hex')||decode(repeat('00',262141),'hex'),'base64')))$$,'Organizer publishes bounded JPEG');
select lives_ok($$select public.review_player_photo('eee30000-0000-4000-8000-000000000001','approve','Written consent reviewed',jsonb_build_object('jpeg_base64',encode(decode('ffd8ff','hex')||decode(repeat('00',262141),'hex'),'base64')))$$,'same approval retry idempotent');
set local role anon;
select is((select count(*)::int from public.public_player_photos where player_id='eee20000-0000-4000-8000-000000000001'),1,'anonymous viewer sees approved projection');
select is((select mime_type from public.public_player_photos where player_id='eee20000-0000-4000-8000-000000000001'),'image/jpeg','public projection has fixed JPEG mime');
select is((select octet_length(decode(content_base64,'base64')) from public.public_player_photos where player_id='eee20000-0000-4000-8000-000000000001'),262144,'maximum bounded JPEG survives canonical encoding');
select throws_ok($$select * from public.player_photo_assets$$,'42501',null,'private asset/consent metadata denied anonymously');
select is((select count(*)::int from storage.objects where bucket_id='player-private'),0,'anonymous reader sees no originals or evidence');
select throws_ok($$select evidence_path from public.public_player_photos$$,'42703',null,'public projection contains no evidence path');
select throws_ok($$select public.review_player_photo('eee30000-0000-4000-8000-000000000001','revoke','Unauthenticated')$$,'42501',null,'anonymous publication changes denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eee00000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.review_player_photo('eee30000-0000-4000-8000-000000000001','revoke','Guardian withdrew permission')$$,'Organizer revokes publication');
select is((select count(*)::int from storage.objects where bucket_id='player-private' and name like 'eee20000-0000-4000-8000-000000000001/%'),2,'private originals/evidence retained after withdrawal');
select is((select before_state->>'state' from public.audit_logs where action='photo.revoke' and entity_id='eee30000-0000-4000-8000-000000000001'),'approved','revocation preserves before state audit');
select throws_ok($$delete from public.player_photo_assets$$,'42501',null,'photo history deletion denied');
set local role anon;
select is((select count(*)::int from public.public_player_photos where player_id='eee20000-0000-4000-8000-000000000001'),0,'revocation immediately removes public read');
select is(public.is_player_photo_approved('eee30000-0000-4000-8000-000000000001'),false,'approval visibility is revoked');
select * from finish();
rollback;
